  const stack = [];
  let drops = nums.length - k;

  for (const num of nums) {
    while (drops > 0 && stack.length > 0 && stack[stack.length - 1] > num) {
      stack.pop();
      drops--;
    }
    stack.push(num);
  }
  return stack.slice(0, k);
}

