function mostCompetitive(nums, k) {
  // Pick each answer position greedily: the smallest value that still leaves room for the rest.
  const answer = [];
  let start = 0;
  for (let picked = 0; picked < k; picked++) {
    const lastAllowed = nums.length - (k - picked);
    let bestIndex = start;
    for (let i = start + 1; i <= lastAllowed; i++) if (nums[i] < nums[bestIndex]) bestIndex = i;
    answer.push(nums[bestIndex]);
    start = bestIndex + 1;
  }
  return answer;
}

