function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1500 + pick(501) : 1 + pick(10);
  const top = rand() < 0.3 ? 1000000000 : size === 'large' ? 1000 : 9;
  const nums = Array.from({ length: n }, () => pick(top + 1));
  if (rand() < 0.2) nums.sort((a, b) => rand() < 0.5 ? a - b : b - a);
  const k = 1 + pick(n);
  return [nums, k];
}
